SELECT * FROM (
SELECT arxiv_id, title, published, topic, abstract FROM papers WHERE title LIKE '%Model Context Protocol%' OR title LIKE '%MCP%' OR abstract LIKE '%Model Context Protocol%' OR abstract LIKE '% MCP %' OR abstract LIKE '%(MCP)%' OR topic = 'mcp-and-frameworks' ORDER BY published DESC LIMIT 10
) LIMIT 51

SELECT * FROM (
SELECT arxiv_id, title, published, abstract FROM papers WHERE arxiv_id = '2606.05339'
) LIMIT 51

